import{_ as a,o as l,c as e,ak as o}from"./chunks/framework.DKi5cyCJ.js";const g=JSON.parse('{"title":"GitLab 本地部署 · 00 编排","description":"编排内网 GitLab CE Omnibus 本地部署全流程（编号 Skills 01–07），参数化主机与数据路径以便换服务器复用。 在用户说本地 GitLab 部署、换服务器重装、执行 gitlab-local、按步骤搭仓时使用。","frontmatter":{"name":"gitlab-local-00-orchestrate","description":"编排内网 GitLab CE Omnibus 本地部署全流程（编号 Skills 01–07），参数化主机与数据路径以便换服务器复用。 在用户说本地 GitLab 部署、换服务器重装、执行 gitlab-local、按步骤搭仓时使用。"},"headers":[],"relativePath":"docs/assets/attachments/gitlab-skills/gitlab-local-00-orchestrate/SKILL.md","filePath":"docs/assets/attachments/gitlab-skills/gitlab-local-00-orchestrate/SKILL.md"}'),d={name:"docs/assets/attachments/gitlab-skills/gitlab-local-00-orchestrate/SKILL.md"};function i(c,t,r,s,n,b){return l(),e("div",null,[...t[0]||(t[0]=[o('<h1 id="gitlab-本地部署-·-00-编排" tabindex="-1">GitLab 本地部署 · 00 编排 <a class="header-anchor" href="#gitlab-本地部署-·-00-编排" aria-label="Permalink to &quot;GitLab 本地部署 · 00 编排&quot;">​</a></h1><h2 id="目标" tabindex="-1">目标 <a class="header-anchor" href="#目标" aria-label="Permalink to &quot;目标&quot;">​</a></h2><p>按固定顺序驱动可复用模块，在 <strong>Ubuntu 22.04 + Omnibus GitLab CE + 内网 HTTP</strong> 上完成「可登录、可建仓、可 clone/push、有备份」。</p><p>本系列 Skills 位于项目：<code>.cursor/skills/gitlab-local-*</code>。</p><h2 id="换服务器时先做" tabindex="-1">换服务器时先做 <a class="header-anchor" href="#换服务器时先做" aria-label="Permalink to &quot;换服务器时先做&quot;">​</a></h2><ol><li>读取 <a href="./env-template.html">env-template.md</a>，让用户填写/确认变量（至少 <code>GITLAB_HOST</code>、<code>EXTERNAL_URL</code>、<code>SSH_USER</code>）。</li><li>将会话内生效的变量列表回显给用户确认（<strong>不含密码</strong>）。</li><li>从 <strong>01</strong> 开始执行；已完成的步骤可跳过，但须记录跳过原因。</li></ol><h2 id="执行顺序-强制" tabindex="-1">执行顺序（强制） <a class="header-anchor" href="#执行顺序-强制" aria-label="Permalink to &quot;执行顺序（强制）&quot;">​</a></h2><table tabindex="0"><thead><tr><th>序号</th><th>Skill</th><th>产出门槛（未达成不得进下一步）</th></tr></thead><tbody><tr><td>01</td><td><code>gitlab-local-01-probe</code></td><td>SSH 可达；已记录 CPU/内存/磁盘形态 <code>DISK_CASE</code></td></tr><tr><td>02</td><td><code>gitlab-local-02-sysprep</code></td><td>依赖包、时区、防火墙/80 端口就绪</td></tr><tr><td>03</td><td><code>gitlab-local-03-datadisk</code></td><td>数据落盘策略确定；B/C 时目录存在</td></tr><tr><td>04</td><td><code>gitlab-local-04-install</code></td><td><code>gitlab-ctl status</code> 正常；Web 可开；管理员已改密</td></tr><tr><td>05</td><td><code>gitlab-local-05-admin</code></td><td>关公开注册；Group/角色/保护分支约定落地</td></tr><tr><td>06</td><td><code>gitlab-local-06-client</code></td><td>至少一台开发机 SSH Key + clone/push 成功</td></tr><tr><td>07</td><td><code>gitlab-local-07-backup</code></td><td>手动备份成功；cron 或等价策略已设</td></tr></tbody></table><p>权威长文（人类阅读）：项目根目录 <code>1.gitlab本地配置指南.md</code>。<strong>执行以各编号 Skill 为准。</strong></p><h2 id="agent-行为规则" tabindex="-1">Agent 行为规则 <a class="header-anchor" href="#agent-行为规则" aria-label="Permalink to &quot;Agent 行为规则&quot;">​</a></h2><ol><li><strong>一次只跑一个编号 Skill</strong>，除非用户明确说「从头跑完全流程」。</li><li>每步结束输出：<code>完成项</code> / <code>未完成项</code> / <code>下一步 Skill 名</code>。</li><li>破坏性操作（<code>mkfs</code>、删数据、restore）必须二次确认设备名/路径。</li><li>禁止把密码写入 skill、指南、git 仓库；口令只口头/密钥管理传递。</li><li>默认 <code>EXTERNAL_URL=http://$GITLAB_HOST</code>；不上公网、本期不做 Runner/HTTPS/LDAP。</li><li>服务器命令经 SSH：<code>ssh $SSH_USER@$GITLAB_HOST &#39;...&#39;</code>；开发机命令在本地执行。</li></ol><h2 id="全流程验收-07-之后" tabindex="-1">全流程验收（07 之后） <a class="header-anchor" href="#全流程验收-07-之后" aria-label="Permalink to &quot;全流程验收（07 之后）&quot;">​</a></h2><ul><li>[ ] Web：<code>$EXTERNAL_URL</code> 可登录</li><li>[ ] 公开注册已关</li><li>[ ] 数据盘策略与 <code>git_data_dirs</code>/<code>backup_path</code> 一致（若适用）</li><li>[ ] 保护分支已设</li><li>[ ] 开发机 <code>git clone</code> / <code>push</code> OK</li><li>[ ] <code>gitlab-backup create</code> 有产物；<code>gitlab.rb</code> + <code>gitlab-secrets.json</code> 有副本</li></ul><h2 id="触发话术示例" tabindex="-1">触发话术示例 <a class="header-anchor" href="#触发话术示例" aria-label="Permalink to &quot;触发话术示例&quot;">​</a></h2><ul><li>「用 gitlab-local 从 01 开始」</li><li>「换服务器，HOST=x.x.x.x，按编排重装」</li><li>「执行 gitlab-local-04-install」</li></ul>',15)])])}const u=a(d,[["render",i]]);export{g as __pageData,u as default};
